class ValidatorTest {

	@Test
	void nameEndsWithValid() {
		User user = new User("Diego Krupitza", "foo@bar.com", 22);

		Validator<User> validator = ValidatorBuilder.<User> of()
				.constraint(User::getName, "name", c -> c.endsWith("Krupitza")).build();

