class ValidationTest {

	@Test
	void bimapSuccess() {
		final Validation<String, String> validation = Validation.success("test");
		final Validation<String, String> bimap = validation.bimap(
				errors -> errors.stream().map(String::toUpperCase).collect(toList()),
